                    "description": "Имя ветеринара",
                },
                "batch_number": {
                    "type": "string",
                    "description": "Номер серии вакцины",
                },
                "notes": {
                    "type": "string",
                    "description": "Заметки",
                },
            },
            "required": ["pet_name", "vaccine_name", "date"],
        },
    }


